     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.RatePlan;
     4	import com.pousadamarealta.domain.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	
    10	public class PricingService {
    11	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    12	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    13	
    14	    public BigDecimal calculateNightlyRate(Room room, LocalDate night) {
    15	        BigDecimal baseRate = room.getNightlyRate();
    16	
    17	        if (isHighSeason(night)) {
    18	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    19	                    .setScale(2, RoundingMode.HALF_EVEN);
    20	        }
    21	
    22	        return baseRate;
    23	    }
    24	
    25	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    26	        BigDecimal subtotal = BigDecimal.ZERO;
    27	        LocalDate current = checkIn;
    28	
    29	        while (current.isBefore(checkOut)) {
    30	            BigDecimal nightlyRate = calculateNightlyRate(room, current);
    31	            subtotal = subtotal.add(nightlyRate);
    32	            current = current.plusDays(1);
    33	        }
    34	
    35	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    36	    }
    37	
    38	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    39	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    40	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
    41	                    .setScale(2, RoundingMode.HALF_EVEN);
    42	        }
    43	
    44	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
    45	    }
    46	
    47	    private boolean isHighSeason(LocalDate date) {
    48	        int month = date.getMonthValue();
    49	        int day = date.getDayOfMonth();
    50	
    51	        if (month == 7) {
    52	            return true;
    53	        }
    54	
    55	        if (month == 12 && day >= 15) {
    56	            return true;
    57	        }
    58	
    59	        if (month == 1 || month == 2) {
    60	            return true;
    61	        }
    62	
    63	        return false;
    64	    }
    65	}
