    43	
    44	    public String generateRevenueReport(int year, int month) {
    45	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(year, month);
    46	
    47	        StringBuilder csv = new StringBuilder();
    48	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    49	
    50	        BigDecimal total = BigDecimal.ZERO;
    51	
    52	        for (Reservation reservation : reservations) {
    53	            BigDecimal amount = reservation.getAmountPaid();
    54	            if (reservation.getRefund() != null) {
    55	                amount = amount.subtract(reservation.getRefund());
    56	            }
    57	            total = total.add(amount);
    58	
    59	            csv.append(String.format(Locale.US, "%d,%s,%s,%s,%s,%.2f\n",
    60	                    reservation.getId(),
    61	                    reservation.getRoomNumber(),
    62	                    reservation.getCheckIn().format(DATE_FORMATTER),
    63	                    reservation.getCheckOut().format(DATE_FORMATTER),
    64	                    reservation.getStatus(),
    65	                    amount));
    66	        }
    67	
    68	        csv.append(String.format(Locale.US, "total,%.2f", total));
    69	
    70	        return csv.toString();
    71	    }
