    13	public class ReservationService {
    14	    private final ReservationRepository reservationRepository;
    15	    private final RoomRepository roomRepository;
    16	    private final PricingService pricingService;
    17	    private final EventPublisher eventPublisher;
    18	
    19	    public ReservationService(
    20	            ReservationRepository reservationRepository,
    21	            RoomRepository roomRepository,
    22	            PricingService pricingService,
    23	            EventPublisher eventPublisher) {
    24	        this.reservationRepository = reservationRepository;
    25	        this.roomRepository = roomRepository;
    26	        this.pricingService = pricingService;
    27	        this.eventPublisher = eventPublisher;
    28	    }
