    30	    public Reservation createReservation(
    31	            String roomNumber,
    32	            String guestName,
    33	            String guestEmail,
    34	            String guestCpf,
    35	            LocalDate checkIn,
    36	            LocalDate checkOut,
    37	            int guests,
    38	            RatePlan ratePlan) {
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new IllegalArgumentException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (guests < 1) {
    45	            throw new IllegalArgumentException("At least one guest is required");
    46	        }
    47	
    48	        Room room = roomRepository.findByNumber(roomNumber)
    49	                .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    50	
    51	        if (guests > room.getCapacity()) {
    52	            throw new CapacityExceededException("Room capacity exceeded");
    53	        }
    54	
    55	        List<Reservation> conflicts = reservationRepository.findConflicting(
    56	                roomNumber, checkIn, checkOut, null);
    57	
    58	        if (!conflicts.isEmpty()) {
    59	            throw new RoomUnavailableException("Room is not available for the selected dates");
    60	        }
    61	
    62	        Reservation reservation = new Reservation();
    63	        reservation.setRoomNumber(roomNumber);
    64	        reservation.setGuestName(guestName);
    65	        reservation.setGuestEmail(guestEmail);
    66	        reservation.setGuestCpf(guestCpf);
    67	        reservation.setCheckIn(checkIn);
    68	        reservation.setCheckOut(checkOut);
    69	        reservation.setGuests(guests);
    70	        reservation.setRatePlan(ratePlan);
    71	
    72	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    73	        reservation.setNights(nights);
    74	
    75	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
