    18	    private static final Locale BRAZIL_LOCALE = new Locale("pt", "BR");
    19	
    20	    public GuestNotificationListener(MessageRepository messageRepository, RoomRepository roomRepository) {
    21	        this.messageRepository = messageRepository;
    22	        this.roomRepository = roomRepository;
    23	    }
    24	
    25	    @Override
    26	    public void handle(ReservationConfirmedEvent event) {
    27	        Reservation reservation = event.reservation();
    28	        String receipt = buildReceipt(reservation);
    29	
    30	        String body = String.format("""
    31	                Olá, %s!
    32	
    33	                Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    34	
    35	                %s
    36	
    37	                A entrada é a partir das 14h, e a saída, até as 12h.
    38	                Até breve!""", reservation.getGuestName(), receipt);
    39	
    40	        Message message = new Message(
    41	                "EMAIL",
    42	                reservation.getGuestEmail(),
    43	                "Reserva confirmada - Pousada Maré Alta",
    44	                body
    45	        );
    46	
    47	        messageRepository.save(message);
    48	    }
    49	
    50	    private String buildReceipt(Reservation reservation) {
    51	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    52	
    53	        StringBuilder sb = new StringBuilder();
    54	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
    55	        sb.append(String.format("Hóspede: %s (CPF %s)%n",
    56	                reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
    57	        sb.append(String.format("Quarto: %s (%s)%n",
    58	                reservation.getRoomNumber(), room.getType()));
    59	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
    60	                reservation.getCheckIn().format(DATE_FORMATTER),
    61	                reservation.getCheckOut().format(DATE_FORMATTER),
    62	                reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias"));
    63	        sb.append(String.format("Diárias: %s%n", formatCurrency(reservation.getSubtotal())));
    64	
    65	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    66	            sb.append(String.format("Desconto: %s%n", formatCurrency(reservation.getDiscount())));
    67	        }
    68	
    69	        sb.append(String.format("Total: %s", formatCurrency(reservation.getTotal())));
    70	
    71	        return sb.toString();
    72	    }
    73	
    74	    private String formatCpf(String cpf) {
    75	        return cpf.replaceAll("(\\d{3})(\\d{3})(\\d{3})(\\d{2})", "$1.$2.$3-$4");
    76	    }
    77	
    78	    private String formatCurrency(BigDecimal amount) {
    79	        NumberFormat formatter = NumberFormat.getCurrencyInstance(BRAZIL_LOCALE);
