    52	
    53	        StringBuilder sb = new StringBuilder();
    54	        sb.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
    55	        sb.append(String.format("Hóspede: %s (CPF %s)%n",
    56	                reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
    57	        sb.append(String.format("Quarto: %s (%s)%n",
    58	                reservation.getRoomNumber(), room.getType()));
    59	        sb.append(String.format("Entrada: %s | Saída: %s | %s%n",
    60	                reservation.getCheckIn().format(DATE_FORMATTER),
    61	                reservation.getCheckOut().format(DATE_FORMATTER),
    62	                reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias"));
    63	        sb.append(String.format("Diárias: %s%n", formatCurrency(reservation.getSubtotal())));
