    10	
    11	public class Database {
    12	    private final HikariDataSource dataSource;
    13	
    14	    public Database(String jdbcUrl, String username, String password) {
    15	        HikariConfig config = new HikariConfig();
    16	        config.setJdbcUrl(jdbcUrl);
    17	        config.setUsername(username);
    18	        config.setPassword(password);
    19	        config.setMaximumPoolSize(10);
    20	        config.setAutoCommit(true);
    21	
    22	        this.dataSource = new HikariDataSource(config);
    23	        initializeSchema();
    24	    }
    25	
    26	    private void initializeSchema() {
    27	        try (Connection conn = getConnection();
    28	             Statement stmt = conn.createStatement()) {
    29	
    30	            stmt.execute("""
    31	                    CREATE TABLE IF NOT EXISTS rooms (
    32	                        number VARCHAR(10) PRIMARY KEY,
    33	                        type VARCHAR(20) NOT NULL,
    34	                        capacity INT NOT NULL,
    35	                        nightly_rate DECIMAL(10, 2) NOT NULL
    36	                    )
    37	                    """);
    38	
    39	            stmt.execute("""
    40	                    CREATE TABLE IF NOT EXISTS reservations (
    41	                        id SERIAL PRIMARY KEY,
    42	                        room_number VARCHAR(10) NOT NULL,
    43	                        guest_name VARCHAR(255) NOT NULL,
    44	                        guest_email VARCHAR(255) NOT NULL,
    45	                        guest_cpf VARCHAR(14) NOT NULL,
    46	                        check_in DATE NOT NULL,
    47	                        check_out DATE NOT NULL,
    48	                        guests INT NOT NULL,
    49	                        rate_plan VARCHAR(20) NOT NULL,
    50	                        nights INT NOT NULL,
    51	                        subtotal DECIMAL(10, 2) NOT NULL,
    52	                        discount DECIMAL(10, 2) NOT NULL,
    53	                        total DECIMAL(10, 2) NOT NULL,
    54	                        status VARCHAR(20) NOT NULL,
    55	                        amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    56	                        refund DECIMAL(10, 2),
    57	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
    58	                    )
    59	                    """);
    60	
    61	            stmt.execute("""
    62	                    CREATE TABLE IF NOT EXISTS messages (
    63	                        id SERIAL PRIMARY KEY,
    64	                        channel VARCHAR(20) NOT NULL,
    65	                        recipient VARCHAR(255) NOT NULL,
    66	                        subject TEXT NOT NULL,
    67	                        body TEXT NOT NULL
    68	                    )
    69	                    """);
    70	
    71	            long count = 0;
    72	            try (var rs = stmt.executeQuery("SELECT COUNT(*) FROM rooms")) {
    73	                if (rs.next()) {
    74	                    count = rs.getLong(1);
    75	                }
    76	            }
    77	
    78	            if (count == 0) {
    79	                stmt.execute("""
    80	                        INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
