    84	                        ('202', 'DELUXE', 3, 389.90),
    85	                        ('301', 'SUITE', 4, 579.90)
    86	                        """);
    87	            }
    88	
    89	        } catch (SQLException e) {
    90	            throw new RuntimeException("Failed to initialize database schema", e);
    91	        }
    92	    }
