     9	
    10	public class MessageRepository {
    11	    private final Database database;
    12	
    13	    public MessageRepository(Database database) {
    14	        this.database = database;
    15	    }
    16	
    17	    public Message save(Message message) {
    18	        String sql = "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)";
    19	
    20	        try (Connection conn = database.getConnection();
    21	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    22	
    23	            stmt.setString(1, message.getChannel());
    24	            stmt.setString(2, message.getTo());
    25	            stmt.setString(3, message.getSubject());
    26	            stmt.setString(4, message.getBody());
    27	
    28	            stmt.executeUpdate();
    29	
    30	            try (ResultSet rs = stmt.getGeneratedKeys()) {
    31	                if (rs.next()) {
    32	                    message.setId(rs.getLong(1));
    33	                }
    34	            }
    35	
    36	        } catch (SQLException e) {
    37	            throw new RuntimeException("Failed to save message", e);
    38	        }
    39	
    40	        return message;
    41	    }
